import pytest
from summarize import summarize

def test_basic_summarization():
    """Test basic summarization logic."""
    data = [
        {'region': 'North', 'revenue': 100.5},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': '50.0'}
    ]
    expected = {'North': 150.5, 'South': 200.0}
    assert summarize(data) == expected

def test_empty_list():
    """Test with an empty input list."""
    assert summarize([]) == {}

def test_missing_region():
    """Test handling rows without a region."""
    data = [{'revenue': 100}]
    assert summarize(data) == {}

def test_unparseable_revenue():
    """Test ignoring rows with missing or unparseable revenue."""
    data = [
        {'region': 'East', 'revenue': 50},
        {'region': 'West', 'revenue': 'invalid'},
        {'region': 'East', 'revenue': '25.5'},
        {'region': 'North', 'revenue': None},
        {'region': 'North', 'revenue': 0}
    ]
    expected = {'East': 75.5, 'North': 0.0}
    assert summarize(data) == expected

def test_mixed_revenue_types():
    """Test handling various numeric types (int, float, str)."""
    data = [
        {'region': 'A', 'revenue': 10},
        {'region': 'A', 'revenue': '20.5'},
        {'region': 'B', 'revenue': 5.0}
    ]
    expected = {'A': 30.5, 'B': 5.0}
    assert summarize(data) == expected

